extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var basket := await instantiate_main_scene() as Sprite2D
	if not check("basket_exists", basket != null, "La scena principale Basket si istanzia correttamente"):
		return

	var spawn_timer = basket.get_node_or_null("SpawnTimer") as Timer
	if spawn_timer:
		spawn_timer.stop()
	var wave_timer = basket.get_node_or_null("WaveTimer") as Timer
	if wave_timer:
		wave_timer.stop()

	var stars = get_prop(basket, "stars")
	if stars is Array:
		for item in stars:
			if is_instance_valid(item):
				item.queue_free()
		stars.clear()

	var rubies = get_prop(basket, "rubies")
	if rubies is Array:
		for ruby in rubies:
			if is_instance_valid(ruby):
				ruby.queue_free()
		rubies.clear()

	for child in basket.get_children():
		if child is Sprite2D and child.name != "Shadow" and child.name != "Handle":
			child.queue_free()

	var initial_lives = get_prop(basket, "INITIAL_LIVES", 3)
	var current_lives = get_prop(basket, "lives", initial_lives)
	check("initial_lives", current_lives == initial_lives, "Le vite iniziali devono essere %d (trovate %d)" % [initial_lives, current_lives])

	call_if_exists(basket, "take_damage", [1])
	await wait_frames(2)

	var expected_lives_after_first = initial_lives - 1
	var lives_after_first = get_prop(basket, "lives", 0)
	check("lives_reduced", lives_after_first == expected_lives_after_first, "Dopo il primo danno le vite scendono a %d (trovate %d)" % [expected_lives_after_first, lives_after_first])

	var is_inv = get_prop(basket, "is_invulnerable", false)
	check("is_invulnerable_true", is_inv == true, "Dopo aver subito danno il cesto deve essere invulnerabile")
	check("modulate_semi_transparent", basket.modulate.a < 0.9, "Il cesto diventa semitrasparente (modulate.a ridotto, trovato %.2f)" % basket.modulate.a)

	await wait_seconds(0.5)
	call_if_exists(basket, "take_damage", [1])
	await wait_frames(2)
	var lives_during_inv = get_prop(basket, "lives", 0)
	check("damage_ignored", lives_during_inv == expected_lives_after_first, "Un colpo subito durante l'invulnerabilità non deve togliere vite (vite trovate %d)" % lives_during_inv)

	await wait_seconds(0.6)
	var is_inv_after = get_prop(basket, "is_invulnerable", true)
	check("invulnerability_ended", is_inv_after == false, "Trascorsa l'attesa di 1 secondo l'invulnerabilità termina")
	check("modulate_restored", basket.modulate.a == 1.0, "L'opacità modulate.a torna a 1.0 (trovato %.2f)" % basket.modulate.a)
